-- Changes: adds the Explore lists that members open from Explore, Campus life and Freshers: societies, student discounts, support services, volunteering and the freshers checklist (98 rows into public.explore_content, all source 'ubp' and status 'published', which the app shows with the From UBP tag). Destructive: no (insert only; a row with the same kind and title that UBP already wrote is skipped). Undo: delete from public.explore_content where source = 'ubp';
--
-- Why: production has 0 rows in explore_content, so every Explore list would be
-- empty for a store reviewer. This is the supabase/seed/explore_content_seed.sql
-- content (researched in November 2026, sources and check dates in
-- supabase/seed/README.md), moved into a migration so it can be applied the same
-- way as everything else, with these changes:
--   * Scholarships rows are NOT included (28 rows). No screen reads them:
--     Explore, Scholarships is the written guide in app/src/constants/
--     scholarshipGuides.js, and ExploreListScreen has no scholarships list.
--   * The 6 'Example: ...' society rows are NOT included. The app already adds
--     its own clearly stamped Example societies on the phone
--     (app/src/constants/exampleSocieties.js), so these would show twice.
--   * An empty url is stored as null.
--   * Idempotent per row instead of all or nothing: a row is skipped when UBP
--     already has a row with the same kind and title. Safe to run more than once.
--
-- Not invented: every row came from the official page named in the seed README.
-- Dates, phone numbers and fees change, so re-open the pages in the README
-- before the day you submit. Each row already says to confirm details on the
-- official page.
--
-- Not applied by the build. The founder applies it.

insert into public.explore_content (kind, title, subtitle, body, url, tags, institution, sort, source, status)
select v.kind, v.title, v.subtitle, v.body, nullif(v.url, ''), v.tags, v.institution, v.sort, v.source, v.status
from (values
  ('discounts', 'Student Leap Card', '50 percent off public transport for full-time students.', 'TFI says you get 50 percent off public transport fares with a valid Young Adult or Student Leap Card. Dublin Bus lists the Student card for full-time students aged 16 to 18 or 26 and over. Order online at leapcard.ie, then go to a Student Leap Agent to prove you are a student and collect the card. Age rules have changed before, so check leapcard.ie. Checked November 2026. Confirm details on the official page.', 'https://www.dublinbus.ie/journey-information/college-transport-hub/save-with-public-transport', array['transport','discount','leap-card']::text[], null, 10, 'ubp', 'published'),
  ('discounts', 'Young Adult Leap Card', 'Same 50 percent off, for everyone aged 19 to 25.', 'If you are 19 to 25 you can get a Young Adult Leap Card whether or not you are a student. It gives the same 50 percent off fares as the Student card. Order it at leapcard.ie. You need a valid Young Adult or Student Leap Card to get TFI Go fares on commercial bus operators. Checked November 2026. Confirm details on the official page.', 'https://www.transportforireland.ie/fares/50-discount-for-young-adult-and-student-leap-card-holders-on-commercial-bus-operators/', array['transport','discount','leap-card']::text[], null, 20, 'ubp', 'published'),
  ('discounts', 'Irish Rail student and young adult fares', '50 percent off InterCity adult fares.', 'Only the TFI Student Leap Card, the TFI Young Adult (19-25) Leap Card and the Translink yLink card are valid for student fares. The Leap card is used as proof of your discount. You cannot tag on and pay for InterCity journeys with a Leap card. Always book a single ticket, not a return. Without the right ticket and card the fine is 100 euro plus the fare. Checked November 2026. Confirm details on the official page.', 'https://www.irishrail.ie/en-ie/rail-fares-and-tickets/students', array['transport','discount','rail']::text[], null, 30, 'ubp', 'published'),
  ('discounts', 'Luas student fares', 'Cheaper Luas fares with a Student Leap Card.', 'At the time of checking, the Luas student 90 Minute Fare was 1.00 euro against 2.00 euro for adults. The student Short Fare was 0.75 euro against 1.50 euro. Multi-operator caps on the card across Dublin Bus, Luas, DART and Commuter Rail were 3.00 euro a day and 12.00 euro a week. You must be studying in Ireland and eligible for a Student Leap Card. Checked November 2026. Confirm details on the official page.', 'https://www.luas.ie/student-tickets', array['transport','discount','dublin']::text[], null, 40, 'ubp', 'published'),
  ('discounts', '50 percent off coach services', 'Student and Young Adult Leap Card discount on many private coach operators.', 'Participating operators include Aircoach, Expressway, CityLink, Dublin Coach, J.J. Kavanagh, Dublin Express and Wexford Bus. Each operator uses a different method. Some take the discount from your Leap card, some sell discounted tickets online, and some use the TFI Go app. Carry your card when you travel. Checked November 2026. Confirm details on the official page.', 'https://www.transportforireland.ie/fares/50-discount-for-young-adult-and-student-leap-card-holders-on-commercial-bus-operators/', array['transport','discount','coach']::text[], null, 50, 'ubp', 'published'),
  ('discounts', 'UNiDAYS', 'Free student discount platform. Verify once a year.', 'UNiDAYS is free. Register with your personal email and verify your student status. Many colleges verify you instantly, or you can send in a student ID card. You get 12 months of access, then you re-verify. You cannot re-verify once you leave your college. Offers change often, so check the brand page before you buy. Checked November 2026. Confirm details on the official page.', 'https://www.myunidays.com/IE/en-IE', array['discount','online','free']::text[], null, 60, 'ubp', 'published'),
  ('discounts', 'Student Beans', 'Free student discounts for students and apprentices.', 'Discounts are for people in full-time education with a personal college email or a student iD. That includes university students and apprentices. If your email domain is recognised you are verified straight away. You re-verify every year. Use a code online or show your Student Beans iD in store. Checked November 2026. Confirm details on the official page.', 'https://www.studentbeans.com/ie/how-it-works', array['discount','online','apprentice','free']::text[], null, 70, 'ubp', 'published'),
  ('discounts', 'ISIC student card', 'International student ID with a discounts app.', 'ISIC is an international student ID. You can order it through isic.ie and use the app for a digital card. Its Discounts in Ireland page lists offers across entertainment, leisure, sport and travel. For Irish Rail and TFI student fares you need a Leap card, not an ISIC. Checked November 2026. Confirm details on the official page.', 'https://www.isic.ie/', array['discount','id','travel']::text[], null, 80, 'ubp', 'published'),
  ('discounts', 'Spotify Premium Student', '6.99 euro a month after a free first month.', 'You must be 18 or over and at an eligible higher-education college. Spotify uses SheerID to check you. It is not offered if you have already tried Premium. You can keep the student plan for up to four years. After that you move to Premium Individual. Checked November 2026. Confirm details on the official page.', 'https://www.spotify.com/ie/student/', array['discount','music','subscription']::text[], null, 90, 'ubp', 'published'),
  ('discounts', 'Apple Music student plan', '6.99 euro a month after a free first month.', 'Verify your student status and you keep student pricing for up to four years while you stay a student. After that the price moves to the individual rate. Free Apple TV for students ends when you stop qualifying. The offer does not work with Family Sharing. Checked November 2026. Confirm details on the official page.', 'https://www.apple.com/ie/apple-music/', array['discount','music','subscription']::text[], null, 100, 'ubp', 'published'),
  ('discounts', 'IFI 25 and Under card', '5 euro tickets at the Irish Film Institute for ages 16 to 25.', 'The 25 and Under card gives 5 euro cinema tickets to 16 to 25 year olds at IFI screenings. Online booking with the card is for people aged 18 and over, one ticket per person. Third-level students can also use concession prices, and concession membership costs 25 euro. Checked November 2026. Confirm details on the official page.', 'https://ifi.ie/visit/ticket-prices/', array['discount','cinema','dublin']::text[], null, 110, 'ubp', 'published'),
  ('discounts', 'Bank of Ireland Third Level account', 'No monthly maintenance fee while you study.', 'You must be 18 or over, in full-time third-level education in Ireland and living in the Republic, or moving there within 45 days. After graduation you get two years with no monthly fee. There is no overdraft on this account, and the bank points to student loans instead. Cash can be lodged or withdrawn at An Post offices. Checked November 2026. Confirm details on the official page.', 'https://personalbanking.bankofireland.com/bank/current-accounts/3rd-level-current-account/', array['banking','discount','account']::text[], null, 120, 'ubp', 'published'),
  ('discounts', 'AIB Student Plus account', 'Student account with an interest-free overdraft.', 'AIB''s fee document lists no account maintenance fee and no overdraft facility fee. It lists interest-free overdrafts of up to 1,000 euro in first and second year and 1,500 euro in third and fourth year. Anything over that is charged at the bank''s standard rate. Tell staff you hold the account to get the benefits in branch. Checked November 2026. Confirm details on the official page.', 'https://www.aib.ie/our-products/current-accounts/Student-Plus-AccTerms-Cons', array['banking','discount','account']::text[], null, 130, 'ubp', 'published'),
  ('support', 'Pieta', 'Free support for suicidal thoughts, self-harm and bereavement.', 'Pieta offers free therapy without a referral, a 24-hour crisis helpline and support for people bereaved by suicide. Crisis helpline: 1800 247 247. Crisis text: text HELP to 51444. Therapy services: 0818 111 126. You can also call if you are worried about someone else. If you are in danger right now, call 999 or 112. Checked November 2026. Confirm details on the official page.', 'https://www.pieta.ie/', array['mental-health','crisis','free','24-hour']::text[], null, 10, 'ubp', 'published'),
  ('support', 'Samaritans Ireland', 'Free, listening support any time, day or night.', 'Call 116 123 for free. They are there 24 hours a day, 365 days a year. If you are in danger right now, call 999 or 112. Checked November 2026. Confirm details on the official page.', 'https://www.samaritans.org/ireland/', array['mental-health','crisis','free','24-hour']::text[], null, 20, 'ubp', 'published'),
  ('support', 'Text About It (50808)', 'Free text line for anything on your mind. Runs 24/7.', 'Text HELLO to 50808 to start a conversation with a trained volunteer. It is run by SpunOut.ie and funded by the HSE. It is anonymous and free on the main networks. Some customers on smaller networks need to text 086 1800 280 instead, and standard rates may apply. It is not for emergencies. If you are in danger right now, call 999 or 112. Checked November 2026. Confirm details on the official page.', 'https://spunout.ie/services/text-about-it/', array['mental-health','text','free','24-hour','young-people']::text[], null, 30, 'ubp', 'published'),
  ('support', 'Jigsaw', 'Free online mental health support for young people.', 'Jigsaw is the National Centre for Youth Mental Health. Its online service offers text chat with a therapist, one-to-one or in a group, plus email support. The online service is free. You can also find your local Jigsaw on their site. Phone: 01 472 7010. Checked November 2026. Confirm details on the official page.', 'https://jigsaw.ie/', array['mental-health','young-people','free','online']::text[], null, 40, 'ubp', 'published'),
  ('support', 'Aware', 'Support for depression, bipolar disorder and anxiety.', 'Aware runs a Support Line on 1800 80 48 48. It also offers support and self-care groups, a free out-of-hours Solace Cafe in Dublin and Waterford, counselling and information. Check the site for the support line hours. Checked November 2026. Confirm details on the official page.', 'https://www.aware.ie/', array['mental-health','support-groups','helpline']::text[], null, 50, 'ubp', 'published'),
  ('support', 'Turn2me', 'Online counselling and peer support groups.', 'Turn2me offers one-to-one online counselling by video or text chat. The page says there are 6 free counselling sessions for Irish residents, for people aged 18 and over. Anonymous peer support groups are free to join. Checked November 2026. Confirm details on the official page.', 'https://www.turn2me.ie/', array['mental-health','counselling','online','free']::text[], null, 60, 'ubp', 'published'),
  ('support', 'MyMind', 'Low-cost counselling, online or in person.', 'MyMind is a not-for-profit counselling and psychotherapy service. It has a reduced rate for full-time third-level students. Its student page is dated, so check the price on the site before you book. There is no referral and no waiting list, according to MyMind. Checked November 2026. Confirm details on the official page.', 'https://mymind.org/counselling-for-students-1', array['mental-health','counselling','low-cost']::text[], null, 70, 'ubp', 'published'),
  ('support', 'Childline', 'Free listening service for children and young people.', 'Call 1800 66 66 66 for free, or chat online. The chat is open 24 hours a day, every day. You can talk about anything. Checked November 2026. Confirm details on the official page.', 'https://www.childline.ie/', array['young-people','helpline','free','24-hour']::text[], null, 80, 'ubp', 'published'),
  ('support', 'HSE Your Mental Health information line', 'Free line to find the right mental health service.', 'Call 1800 111 888 any time. It is free. They can point you to HSE mental health supports and services, and how to access them. The yourmentalhealth.ie site lists services nationally and locally. Checked November 2026. Confirm details on the official page.', 'https://www.hse.ie/mental-health/services-support/your-mental-health-information-line/', array['mental-health','helpline','free','HSE']::text[], null, 90, 'ubp', 'published'),
  ('support', 'Women''s Aid', 'Free, confidential helpline for domestic abuse.', 'The 24-hour National Freephone Helpline is 1800 341 900. It is free and confidential. Women''s Aid also offers instant message support, mornings and evenings, seven days a week. Its page also lists support for young people, men and LGBTI+ people. If you are in danger right now, call 999 or 112. Checked November 2026. Confirm details on the official page.', 'https://www.womensaid.ie/', array['safety','domestic-abuse','helpline','free','24-hour']::text[], null, 100, 'ubp', 'published'),
  ('support', 'Dublin Rape Crisis Centre', '24-hour helpline and webchat after sexual violence.', 'The National 24-Hour Helpline is 1 800 77 8888, a freephone number. There is also a confidential webchat. The site has a guide called Finding Your Way after Sexual Violence. If you are in danger right now, call 999 or 112. Checked November 2026. Confirm details on the official page.', 'https://www.drcc.ie/', array['safety','sexual-violence','helpline','24-hour']::text[], null, 110, 'ubp', 'published'),
  ('support', 'BeLonG To', 'Support for LGBTQ+ young people.', 'BeLonG To is the national organisation supporting LGBTQ+ young people. It lists a one-on-one chat service, professional counselling, a drug and alcohol support service, youth groups and family support. The page does not list a cost or a phone number, so use the contact page. Checked November 2026. Confirm details on the official page.', 'https://www.belongto.org/', array['lgbtq','young-people','counselling']::text[], null, 120, 'ubp', 'published'),
  ('support', 'Student Assistance Fund (money help)', 'Hardship fund through your college. Free to apply.', 'If money is the problem, the Student Assistance Fund can help with books, rent, food, travel, childcare and medical costs. It does not cover tuition or registration fees. Ask the access or student services office at your college. Your application is handled confidentially. Checked November 2026. Confirm details on the official page.', 'https://hea.ie/funding-governance-performance/funding/student-finance/student-assistance-fund/', array['money','hardship','college']::text[], null, 130, 'ubp', 'published'),
  ('support', 'MABS money advice', 'Free, confidential help with money and debt.', 'MABS is a free, independent and confidential service. It gives non-judgemental advice on managing money and problem debt. Helpline: 0818 07 2000, Monday to Friday, 9am to 8pm. Checked November 2026. Confirm details on the official page.', 'https://www.citizensinformationboard.ie/en/services/mabs/', array['money','debt','helpline','free']::text[], null, 140, 'ubp', 'published'),
  ('support', 'Citizens Information phone service', 'Free information on public services and your rights.', 'Call 0818 07 4000, Monday to Friday, 9am to 8pm. It is a confidential information service. Calls to 0818 numbers cost no more than a landline call. There is also a Live Advisor chat for people who find phone calls hard, 9am to 5pm Monday to Friday. Checked November 2026. Confirm details on the official page.', 'https://www.citizensinformationboard.ie/en/services/citizensinformation/cips.html', array['information','rights','helpline']::text[], null, 150, 'ubp', 'published'),
  ('support', 'RTB student renting guide', 'Know your rights as a student tenant.', 'The Residential Tenancies Board explains deposits, rent receipts, registration and disputes for students. Get a written deposit receipt and keep proof of every payment. Digs and short-term lets are not covered by RTB dispute resolution. Talk to your landlord first, then use the RTB if it is not fixed. Checked November 2026. Confirm details on the official page.', 'https://rtb.ie/students/', array['housing','renting','rights']::text[], null, 160, 'ubp', 'published'),
  ('support', 'Threshold', 'Housing and renting advice.', 'Threshold is a housing charity that gives advice to renters. It describes its advice as free and confidential. Visit threshold.ie to get help. Checked November 2026. Confirm details on the official page.', 'https://threshold.ie/', array['housing','renting','free']::text[], null, 170, 'ubp', 'published'),
  ('support', 'Your college counselling service', 'Often free for students. Ask your student services.', 'Many colleges run a student counselling service. Trinity''s service, for example, is free and confidential. Search your college site for counselling, student health or wellbeing. If you are not sure where to start, ask your Students'' Union.', null, array['mental-health','college','counselling']::text[], null, 180, 'ubp', 'published'),
  ('societies', 'UL Law Society', 'University of Limerick. Law society.', 'Listed on the University of Limerick societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ulwolves.ie/societies', array['law','academic']::text[], 'University of Limerick', 10, 'ubp', 'published'),
  ('societies', 'UL Drama Society', 'University of Limerick. Drama society.', 'Listed on the University of Limerick societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ulwolves.ie/societies', array['drama','arts']::text[], 'University of Limerick', 20, 'ubp', 'published'),
  ('societies', 'UL Fashion Society', 'University of Limerick. Fashion society.', 'Listed on the University of Limerick societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ulwolves.ie/societies', array['fashion','arts']::text[], 'University of Limerick', 30, 'ubp', 'published'),
  ('societies', 'UL Games Society', 'University of Limerick. Games society.', 'Listed on the University of Limerick societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ulwolves.ie/societies', array['gaming']::text[], 'University of Limerick', 40, 'ubp', 'published'),
  ('societies', 'UL Philosophy & Debating Society', 'University of Limerick. Philosophy and debating society.', 'Listed on the University of Limerick societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ulwolves.ie/societies', array['debating']::text[], 'University of Limerick', 50, 'ubp', 'published'),
  ('societies', 'Out in UL', 'University of Limerick. LGBTQ+ society.', 'Listed on the University of Limerick societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ulwolves.ie/societies', array['lgbtq','community']::text[], 'University of Limerick', 60, 'ubp', 'published'),
  ('societies', 'UL Environmental Society', 'University of Limerick. Environmental society.', 'Listed on the University of Limerick societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ulwolves.ie/societies', array['environment']::text[], 'University of Limerick', 70, 'ubp', 'published'),
  ('societies', 'UL Cumann Gaelach', 'University of Limerick. Irish language society.', 'Listed on the University of Limerick societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ulwolves.ie/societies', array['irish-language']::text[], 'University of Limerick', 80, 'ubp', 'published'),
  ('societies', 'Enactus Social Entrepreneurship UL', 'University of Limerick. Social entrepreneurship society.', 'Listed on the University of Limerick societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ulwolves.ie/societies', array['entrepreneurship','charity']::text[], 'University of Limerick', 90, 'ubp', 'published'),
  ('societies', 'Galway Law Society', 'University of Galway. Law society.', 'Listed on the University of Galway societies list. Join through the societies site with your student login. Checked November 2026. Confirm details on the official page.', 'https://socs.universityofgalway.ie/societies/', array['law','academic']::text[], 'University of Galway', 100, 'ubp', 'published'),
  ('societies', 'Galway Dramsoc', 'University of Galway. Drama society.', 'Listed on the University of Galway societies list. Join through the societies site with your student login. Checked November 2026. Confirm details on the official page.', 'https://socs.universityofgalway.ie/societies/', array['drama','arts']::text[], 'University of Galway', 110, 'ubp', 'published'),
  ('societies', 'Galway Lit & Deb', 'University of Galway. Literary and debating society.', 'Listed on the University of Galway societies list. Join through the societies site with your student login. Checked November 2026. Confirm details on the official page.', 'https://socs.universityofgalway.ie/societies/', array['debating','literary']::text[], 'University of Galway', 120, 'ubp', 'published'),
  ('societies', 'Galway Climate Action Society', 'University of Galway. Climate action society.', 'Listed on the University of Galway societies list. Join through the societies site with your student login. Checked November 2026. Confirm details on the official page.', 'https://socs.universityofgalway.ie/societies/', array['environment']::text[], 'University of Galway', 130, 'ubp', 'published'),
