  ('societies', 'Galway FilmSoc', 'University of Galway. Film society.', 'Listed on the University of Galway societies list. Join through the societies site with your student login. Checked November 2026. Confirm details on the official page.', 'https://socs.universityofgalway.ie/societies/', array['film','arts']::text[], 'University of Galway', 150, 'ubp', 'published'),
  ('societies', 'Galway St. Vincent de Paul Society', 'University of Galway. Charity and volunteering society.', 'Listed on the University of Galway societies list. Join through the societies site with your student login. Checked November 2026. Confirm details on the official page.', 'https://socs.universityofgalway.ie/societies/', array['charity','volunteering']::text[], 'University of Galway', 160, 'ubp', 'published'),
  ('societies', 'Galway Video Game Society', 'University of Galway. Video game society.', 'Listed on the University of Galway societies list. Join through the societies site with your student login. Checked November 2026. Confirm details on the official page.', 'https://socs.universityofgalway.ie/societies/', array['gaming']::text[], 'University of Galway', 170, 'ubp', 'published'),
  ('societies', 'UCC Law Society', 'University College Cork. Law society.', 'Listed on the University College Cork societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ucc.ie/en/societies/allsocieties/', array['law','academic']::text[], 'University College Cork', 180, 'ubp', 'published'),
  ('societies', 'UCC Comedy Society', 'University College Cork. Comedy society.', 'Listed on the University College Cork societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ucc.ie/en/societies/allsocieties/', array['comedy','arts']::text[], 'University College Cork', 190, 'ubp', 'published'),
  ('societies', 'UCC Dramatic Society', 'University College Cork. Drama society.', 'Listed on the University College Cork societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ucc.ie/en/societies/allsocieties/', array['drama','arts']::text[], 'University College Cork', 200, 'ubp', 'published'),
  ('societies', 'Bród (LGBTQ+) Society UCC', 'University College Cork. LGBTQ+ society.', 'Listed on the University College Cork societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ucc.ie/en/societies/allsocieties/', array['lgbtq','community']::text[], 'University College Cork', 210, 'ubp', 'published'),
  ('societies', 'Suicide Awareness and Mental Health Society UCC', 'University College Cork. Mental health society.', 'Listed on the University College Cork societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ucc.ie/en/societies/allsocieties/', array['mental-health','community']::text[], 'University College Cork', 220, 'ubp', 'published'),
  ('societies', 'UCC Networking, Technology and Gaming Society', 'University College Cork. Technology and gaming society.', 'Listed on the University College Cork societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ucc.ie/en/societies/allsocieties/', array['gaming','tech']::text[], 'University College Cork', 230, 'ubp', 'published'),
  ('societies', 'Maynooth Law Society', 'Maynooth University. Law society.', 'Listed on the Maynooth University societies list. Create an account with your student number and request membership. Checked November 2026. Confirm details on the official page.', 'https://mulife.ie/', array['law','academic']::text[], 'Maynooth University', 240, 'ubp', 'published'),
