  ('societies', 'Maynooth Pride Society', 'Maynooth University. LGBTQ+ society.', 'Listed on the Maynooth University societies list. Create an account with your student number and request membership. Checked November 2026. Confirm details on the official page.', 'https://mulife.ie/', array['lgbtq','community']::text[], 'Maynooth University', 260, 'ubp', 'published'),
  ('societies', 'Maynooth SVP Society', 'Maynooth University. Charity and volunteering society.', 'Listed on the Maynooth University societies list. Create an account with your student number and request membership. Checked November 2026. Confirm details on the official page.', 'https://mulife.ie/', array['charity','volunteering']::text[], 'Maynooth University', 270, 'ubp', 'published'),
  ('societies', 'Maynooth Film Society', 'Maynooth University. Film society.', 'Listed on the Maynooth University societies list. Create an account with your student number and request membership. Checked November 2026. Confirm details on the official page.', 'https://mulife.ie/', array['film','arts']::text[], 'Maynooth University', 280, 'ubp', 'published'),
  ('societies', 'Trinity Comedy Society', 'Trinity College Dublin. Comedy society.', 'Listed on the Trinity College Dublin societies list. Trinity has more than 120 student-run societies. Find yours on the societies site. Checked November 2026. Confirm details on the official page.', 'https://trinitysocieties.ie/societies', array['comedy','arts']::text[], 'Trinity College Dublin', 290, 'ubp', 'published'),
  ('societies', 'The Hist (College Historical Society)', 'Trinity College Dublin. Debating society.', 'Listed on the Trinity College Dublin societies list. Trinity has more than 120 student-run societies. Find yours on the societies site. Checked November 2026. Confirm details on the official page.', 'https://trinitysocieties.ie/societies', array['debating']::text[], 'Trinity College Dublin', 300, 'ubp', 'published'),
  ('societies', 'Trinity Dance Society', 'Trinity College Dublin. Dance society.', 'Listed on the Trinity College Dublin societies list. Trinity has more than 120 student-run societies. Find yours on the societies site. Checked November 2026. Confirm details on the official page.', 'https://trinitysocieties.ie/societies', array['dance','arts']::text[], 'Trinity College Dublin', 310, 'ubp', 'published'),
  ('societies', 'DCU Clubs and Societies', 'Dublin City University. Search all DCU clubs and societies.', 'DCU lists Clubs and Societies under Student Life, with a Search Clubs & Socs page. Use it to find law, comedy, drama, gaming and more. If nothing fits, the Office of Student Life can help you set up your own. Checked November 2026. Confirm details on the official page.', 'https://dcustudentlife.ie/', array['community']::text[], 'Dublin City University', 320, 'ubp', 'published'),
  ('volunteering', 'Volunteer Ireland', 'Find a volunteer role near you.', 'Volunteer Ireland is the national volunteer development organisation. It supports local Volunteer Centres across Ireland. Use its Find a volunteer role page, or browse volunteering with an organisation, from home, in your community, or abroad. Checked November 2026. Confirm details on the official page.', 'https://www.volunteer.ie/', array['volunteering','national','all-ages']::text[], null, 10, 'ubp', 'published'),
  ('volunteering', 'St Vincent de Paul (SVP)', 'Home visits, shops, child and family services and Young SVP in colleges.', 'SVP lists home visitation, Vincent''s Shops, child and family services and social housing, and Young SVP (Colleges) on its application form. Fill in the short online form. Some roles need Garda vetting. Email info@svp.ie or call +353 1 884 8200. Checked November 2026. Confirm details on the official page.', 'https://www.svp.ie/get-involved/volunteer.aspx', array['volunteering','charity','college']::text[], null, 20, 'ubp', 'published'),
  ('volunteering', 'Irish Red Cross', 'Youth membership from age 4 to 25, with Garda vetting from 16.', 'Anyone aged 4 to 25 can join Irish Red Cross Youth. Find your local branch on the Irish Red Cross site and contact the branch secretary. Members aged 16 and over complete Garda vetting. Under 18s need parental consent. Checked November 2026. Confirm details on the official page.', 'https://redcross.ie/?p=14724', array['volunteering','first-aid','youth']::text[], null, 30, 'ubp', 'published'),
  ('volunteering', 'Habitat for Humanity Ireland Global Village', 'One to two week volunteer builds overseas.', 'Global Village trips are one to two weeks, in teams of about 10 to 25 people. Habitat''s own pages disagree on whether under 18s can join right now, so check with Habitat Ireland first. Email info@habitatireland.ie. Checked November 2026. Confirm details on the official page.', 'https://habitatireland.ie/joinus/volunteerglobally/gv_termsandconditions', array['volunteering','abroad','building']::text[], null, 40, 'ubp', 'published'),
  ('volunteering', 'Special Olympics Ireland', 'Volunteer with athletes and local clubs.', 'Start with the volunteer interest form on the site. You can read about volunteer roles and training. Athletes can use the Find a Club tool to join a local club. Safeguarding is part of volunteering. Checked November 2026. Confirm details on the official page.', 'https://www.specialolympics.ie/', array['volunteering','sport','disability']::text[], null, 50, 'ubp', 'published'),
  ('volunteering', 'TidyTowns', 'Join or start a local TidyTowns group.', 'TidyTowns has run since 1958. More than 900 groups take part. Use Find your TidyTowns Group to join one near you. If there is none, the site has a Start a TidyTowns Group page. Checked November 2026. Confirm details on the official page.', 'https://www.tidytowns.ie/', array['volunteering','community','environment']::text[], null, 60, 'ubp', 'published'),
  ('volunteering', 'Clean Coasts', 'Beach clean-ups and marine litter surveys.', 'Clean Coasts supports more than 2,000 community groups. Register as a Clean Coasts Group, join the 2 Minute Beach Clean, or find events on its Eventbrite page. The Big Beach Clean is one of its initiatives. Checked November 2026. Confirm details on the official page.', 'https://cleancoasts.org/', array['volunteering','environment','coast']::text[], null, 70, 'ubp', 'published'),
  ('volunteering', 'Concern Worldwide in Ireland', 'Collections, fundraising and debate adjudicating.', 'Concern lists debate adjudicators, street and church gate collection volunteers, and fundraising volunteers. Collection shifts are usually a few hours, once or twice a year. The debates information on the page referred to an older school year, so ask Concern what is open now. Email debates@concern.net for debates. Checked November 2026. Confirm details on the official page.', 'https://www.concern.net/volunteer/volunteer-in-ireland', array['volunteering','charity','fundraising']::text[], null, 80, 'ubp', 'published'),
  ('freshers', 'Accept your CAO offer', 'Reply by the date on your offer.', 'Your offer and its reply date are in your CAO account. Reply before the date shown. Applying for 2027 entry? CAO says applications are open and close on 1 February at 5pm. Checked November 2026. Confirm details on the official page.', 'https://www.cao.ie/', array['before you arrive','checklist']::text[], null, 10, 'ubp', 'published'),
  ('freshers', 'Register on your college portal', 'You need it for almost everything.', 'After you accept, your college will tell you how to register. Do it as soon as you can. Fees, timetables and your student ID usually start here.', null, array['before you arrive','checklist']::text[], null, 20, 'ubp', 'published'),
  ('freshers', 'Apply for SUSI', 'The main grant. Do not leave it late.', 'SUSI says online applications for 2026/27 are closed, with a late application process. We could not find the next opening date, so watch susi.ie. Use the Eligibility Indicator on the site to check your chances. Phone 0818 888 777 or email support@susi.ie, Monday to Friday, 9am to 5.30pm. Checked November 2026. Confirm details on the official page.', 'https://www.susi.ie/', array['before you arrive','checklist']::text[], null, 30, 'ubp', 'published'),
  ('freshers', 'Check the Student Assistance Fund', 'Hardship help through your college.', 'If money is tight, ask your access or student services office about the Student Assistance Fund. It can help with books, rent, food and travel. It does not cover tuition. Apply early. Checked November 2026. Confirm details on the official page.', 'https://hea.ie/funding-governance-performance/funding/student-finance/student-assistance-fund/', array['before you arrive','checklist']::text[], null, 40, 'ubp', 'published'),
  ('freshers', 'Ask about access routes and bursaries', 'Check this before you start, not after.', 'If you are from a group under-represented in college, ask the Access Office about the 1916 Bursary and other supports. Each college has a limited number of bursaries. Checked November 2026. Confirm details on the official page.', 'https://hea.ie/funding-governance-performance/funding/student-finance/1916-bursary/', array['before you arrive','checklist']::text[], null, 50, 'ubp', 'published'),
  ('freshers', 'Register with disability support early', 'Supports take time to set up.', 'The Fund for Students with Disabilities pays colleges for supports like assistive technology, learning support and transport. Contact your college disability service before term starts. Checked November 2026. Confirm details on the official page.', 'https://hea.ie/policy/access/fund-for-students-with-disabilities/', array['before you arrive','checklist']::text[], null, 60, 'ubp', 'published'),
  ('freshers', 'Learn your renting rights', 'Read this before you sign a lease.', 'The RTB says to get a written deposit receipt, keep proof of every payment and check if your tenancy is registered. Digs and short-term lets are not covered by RTB dispute resolution. Checked November 2026. Confirm details on the official page.', 'https://rtb.ie/students/', array['before you arrive','checklist']::text[], null, 70, 'ubp', 'published'),
  ('freshers', 'Get a Student or Young Adult Leap Card', '50 percent off public transport.', 'Aged 19 to 25? Get a Young Adult Leap Card. Full-time students aged 16 to 18 or 26 and over can get a Student Leap Card. Order online at leapcard.ie. Checked November 2026. Confirm details on the official page.', 'https://www.transportforireland.ie/fares/50-discount-for-young-adult-and-student-leap-card-holders-on-commercial-bus-operators/', array['money','checklist']::text[], null, 80, 'ubp', 'published'),
  ('freshers', 'Set up a student bank account', 'Compare fees and overdraft rules.', 'Bank of Ireland''s Third Level account has no monthly maintenance fee and no overdraft. AIB''s Student Plus account lists interest-free overdrafts up to set limits. Compare before you choose. Checked November 2026. Confirm details on the official page.', 'https://personalbanking.bankofireland.com/bank/current-accounts/3rd-level-current-account/', array['money','checklist']::text[], null, 90, 'ubp', 'published'),
  ('freshers', 'Sign up for UNiDAYS and Student Beans', 'Free student discounts.', 'Both are free. Register with your college email and verify once a year. Check the offer before you buy. Checked November 2026. Confirm details on the official page.', 'https://www.myunidays.com/IE/en-IE', array['money','checklist']::text[], null, 100, 'ubp', 'published'),
  ('freshers', 'Make a simple budget', 'Know what comes in and goes out.', 'List your grant, wages and family help. Then list rent, food, transport and phone. MABS gives free, confidential money advice on 0818 07 2000, Monday to Friday, 9am to 8pm. Checked November 2026. Confirm details on the official page.', 'https://www.citizensinformationboard.ie/en/services/mabs/', array['money','checklist']::text[], null, 110, 'ubp', 'published'),
  ('freshers', 'Ask about the Back to Education Allowance', 'If you are on a welfare payment.', 'If you get certain social welfare payments and start a full-time course, you may qualify. Apply before the course starts. You cannot hold it with the SUSI maintenance grant. Checked November 2026. Confirm details on the official page.', 'https://www.gov.ie/en/service/418e3f-back-to-education-allowance', array['money','checklist']::text[], null, 120, 'ubp', 'published'),
  ('freshers', 'Go to orientation', 'Meet people before classes get busy.', 'Orientation usually covers your campus, services and societies. Go to as much as you can. Everyone is new.', null, array['week one','checklist']::text[], null, 130, 'ubp', 'published'),
  ('freshers', 'Collect your student ID', 'You need it for the library, labs and exams.', 'Find out where and when to collect your card. Bring photo ID if your college asks for it.', null, array['week one','checklist']::text[], null, 140, 'ubp', 'published'),
  ('freshers', 'Set up your college email', 'Check it every day.', 'Your college will send timetables, fee notices and exam information here. Set up the app on your phone. It is also what you use to verify for student discounts.', null, array['week one','checklist']::text[], null, 150, 'ubp', 'published'),
  ('freshers', 'Learn your timetable', 'Do a practice walk of your week.', 'Find each room and building on campus before your first class. Plan how long it takes to get between them.', null, array['week one','checklist']::text[], null, 160, 'ubp', 'published'),
  ('freshers', 'Join two societies', 'One for fun and one for your goals.', 'Most colleges have dozens of societies. Look for them in your college societies list. Many welcome members who only turn up now and then.', null, array['week one','checklist']::text[], null, 170, 'ubp', 'published'),
  ('freshers', 'Join a club or try a sport', 'Good for your health and for friends.', 'Look at your college sports page or ask at the Students'' Union. Many clubs have beginner sessions in the first weeks.', null, array['week one','checklist']::text[], null, 180, 'ubp', 'published'),
  ('freshers', 'Find the library', 'Learn how to book rooms and borrow.', 'Take a library tour. Find out how to log in to your account and where quiet study rooms are.', null, array['week one','checklist']::text[], null, 190, 'ubp', 'published'),
  ('freshers', 'Find the careers service', 'Go in first year, not final year.', 'The careers service helps with CVs, placements and interviews. Ask what is on in your first term.', null, array['settling in','checklist']::text[], null, 200, 'ubp', 'published'),
  ('freshers', 'Meet your Students'' Union', 'They can help with problems.', 'Your Students'' Union can point you to supports for money, housing and academic issues. Find the office or the website.', null, array['settling in','checklist']::text[], null, 210, 'ubp', 'published'),
  ('freshers', 'Try some volunteering', 'Meet people and build skills.', 'Volunteer Ireland has a Find a volunteer role page. Your college may also have a volunteering society or office. Checked November 2026. Confirm details on the official page.', 'https://www.volunteer.ie/', array['settling in','checklist']::text[], null, 220, 'ubp', 'published'),
  ('freshers', 'Keep your rent receipts', 'You may need them later.', 'Keep your lease, deposit receipt and proof of each rent payment. If there is a dispute, talk to your landlord first. Then you can use the RTB. Checked November 2026. Confirm details on the official page.', 'https://rtb.ie/students/', array['settling in','checklist']::text[], null, 230, 'ubp', 'published'),
  ('freshers', 'Ask about discounts before you pay', 'Many places have student rates.', 'Show your student ID or Leap card where it might help. The IFI 25 and Under card gives 5 euro tickets to ages 16 to 25. Checked November 2026. Confirm details on the official page.', 'https://ifi.ie/visit/ticket-prices/', array['settling in','checklist']::text[], null, 240, 'ubp', 'published'),
  ('freshers', 'Register with a GP', 'Do it before you are sick.', 'Use the HSE GP finder to look for a practice near your term-time address. Contact the practice to register. HSE Live can answer questions on 1800 700 700. Checked November 2026. Confirm details on the official page.', 'https://www2.hse.ie/services/find-a-gp/', array['your health','checklist']::text[], null, 250, 'ubp', 'published'),
  ('freshers', 'Know where your college counselling service is', 'Free at many colleges.', 'Find your college counselling or wellbeing service now, so you know where to go if things get hard. Trinity''s is free and confidential, for example.', null, array['your health','checklist']::text[], null, 260, 'ubp', 'published'),
  ('freshers', 'Save these numbers in your phone', 'For a bad night or a bad week.', 'Samaritans: 116 123, free. Pieta crisis line: 1800 247 247. Text HELLO to 50808. HSE Your Mental Health line: 1800 111 888. If you are in danger, call 999 or 112. Checked November 2026. Confirm details on the official page.', 'https://www.hse.ie/mental-health/services-support/your-mental-health-information-line/', array['your health','checklist']::text[], null, 270, 'ubp', 'published')
) as v(kind, title, subtitle, body, url, tags, institution, sort, source, status)
where not exists (
  select 1 from public.explore_content e
  where e.source = 'ubp' and e.kind = v.kind and e.title = v.title
);
